from pathlib import Path
root=Path(__file__).parent
checks=[]
def check(name,ok): checks.append((name,bool(ok)))
service=(root/'src/subscriptions/subscriptions.service.ts').read_text()
controller=(root/'src/subscriptions/subscriptions.controller.ts').read_text()
entity=(root/'src/subscriptions/subscription.entity.ts').read_text()
booking=(root/'src/appointments/appointments.service.ts').read_text()
doctor=(root/'src/doctors/doctors.service.ts').read_text()
facility=(root/'src/facilities/facilities.service.ts').read_text()
app=(root/'mobile/App.tsx').read_text();client=(root/'mobile/src/api/client.ts').read_text()
doc_ui=(root/'mobile/src/screens/DoctorSubscriptionScreen.tsx').read_text();owner_ui=(root/'mobile/src/screens/OwnerSubscriptionsScreen.tsx').read_text()
migration=(root/'src/database/migrations/1732800000000-CreateDoctorSubscriptionsAndOwnerAudit.ts').read_text()
check('subscription entity models manual payment and expiry',all(x in entity for x in ['durationDays','amountIqd','transferReference','proofUrl','startsAt','expiresAt']))
check('subscription status lifecycle includes pending active rejected expired',all(x in entity for x in ['PENDING','ACTIVE','REJECTED','EXPIRED']))
check('doctor can request and view subscription',"@Post('doctors/me/subscriptions')" in controller and "@Get('doctors/me/subscriptions')" in controller)
check('owner-only subscription approval route',"@Patch('owner/subscriptions/:id/review')" in controller and "@Roles(UserRole.OWNER)" in controller)
check('owner can set approved duration', 'dto.durationDays??row.durationDays' in service)
check('manual approval sets actual start and expiry', 'row.startsAt=now' in service and 'row.expiresAt=new Date' in service)
check('no automatic renewal behavior', 'renewal' not in service.lower() and 'auto-renew' not in service.lower())
check('doctor booking enforces unexpired active subscription', 'DoctorSubscriptionStatus.ACTIVE' in booking and 'subscription.expiresAt <= new Date()' in booking)
check('public doctor directory remains profile-status based', "p.status = :approved" in (root/'src/doctors/doctors.service.ts').read_text())
check('owner dashboard summary includes key counts and revenue',all(x in service for x in ['pendingSubscriptions','activeSubscriptions','subscriptionsRevenueIqd','expiringWithin7Days']))
check('owner can list and deactivate accounts safely',"@Get('owner/users')" in controller and "@Patch('owner/users/:id/status')" in controller and 'user.role===UserRole.OWNER' in service)
check('owner audit trail endpoint and records exist',"@Get('owner/audit-logs')" in controller and 'owner_audit_logs' in migration)
check('doctor profile review writes audit log','doctor_profile_${dto.decision}' in doctor)
check('facility review writes audit log','facility_${status}' in facility)
check('subscription review writes audit log','subscription_${dto.decision}' in service)
check('migration creates subscriptions and audit tables','CREATE TABLE doctor_subscriptions' in migration and 'CREATE TABLE owner_audit_logs' in migration)
check('migration enforces valid subscription amount and duration','CHECK ("durationDays" BETWEEN 1 AND 365)' in migration and 'CHECK ("amountIqd" > 0)' in migration)
check('mobile doctor subscription screen exists and submits request',doc_ui.count('requestSubscription')>=1 and 'سجل طلباتي' in doc_ui)
check('mobile owner screen includes approvals and account management','قبول وتفعيل' in owner_ui and 'تعطيل الحساب' in owner_ui and 'سجل عمليات المالك' in owner_ui)
check('mobile API methods wired','requestSubscription:' in client and 'ownerSummary:' in client and 'reviewSubscription:' in client)
check('both mobile screens are navigable', 'DoctorSubscriptionScreen' in app and 'OwnerSubscriptionsScreen' in app)
check('migration registered in app and data source','DoctorSubscription,OwnerAuditLog' in (root/'src/app.module.ts').read_text() and 'DoctorSubscription,OwnerAuditLog' in (root/'src/database/data-source.ts').read_text())
check('documentation describes manual payment and migration', 'Migration has not been applied' in (root/'docs/phase-v35-owner-subscriptions-and-admin.md').read_text() and 'No automatic renewal' in (root/'docs/phase-v35-owner-subscriptions-and-admin.md').read_text())
for name,ok in checks: print(('PASS' if ok else 'FAIL')+' '+name)
print(f'V35: {sum(ok for _,ok in checks)}/{len(checks)}')
raise SystemExit(0 if all(ok for _,ok in checks) else 1)
